Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MODX=998244353,MODY=1e9+7;
const int MAXN=2e6,MAX=1e6;
ll total_n,cnt;
int total_cnt,final_ans,depth_limit,pw_arr[MAXN],sum_arr[MAXN];
vector<int> data_vec[MAXN];

inline int mod_diff(int x,int y,int m){return (x-y<0)?x-y+m:x-y;}
inline int mod_sum(int x,int y,int m){return (x+y>=m)?x+y-m:x+y;}
inline void build(int level,int val){
	if(val<=total_n){
		++total_cnt;int x=mod_diff(total_cnt,val,MODX);
		data_vec[level-1].push_back(x);sum_arr[level-1]=mod_sum(sum_arr[level-1],x,MODY);
	}
	if(level>6) return;
	for(int i=0;i<=9;++i) build(level+1,val*10+i);
}
inline void process(int level,ll current){
	if(current>total_n) return;
	if(level>1){
		if(10ll*current*MAX>total_n && 1ll*(current+1)*MAX-1<=total_n){
			for(int i=0;i<7;++i){
				int x=((cnt-1ll*current*pw_arr[i])%MODX+MODX)%MODX;
				int p=lower_bound(data_vec[i].begin(),data_vec[i].end(),MODX-x)-data_vec[i].begin();
				final_ans=mod_sum(final_ans,mod_sum(1ll*x*data_vec[i].size()%MODY,sum_arr[i],MODY),MODY);
				final_ans=mod_diff(final_ans,1ll*MODX*(data_vec[i].size()-p)%MODY,MODY);
			}
			cnt+=total_cnt;
			return;
		}
		++cnt;final_ans=mod_sum(final_ans,((cnt-current)%MODX+MODX)%MODX,MODY);
	}
	for(int i=(level==1?1:0);i<=9;++i) process(level+1,current*10+i);
}
int main(){
	scanf("%lld",&total_n);
	pw_arr[0]=1;for(int i=1;i<9;++i) pw_arr[i]=10*pw_arr[i-1];
	build(1,0);
	for(int i=0;i<7;++i)
		sort(data_vec[i].begin(),data_vec[i].end());
	process(1,0);
	printf("%d\n",final_ans);
	return 0;
}
